import React, { FC, useEffect, useState } from "react";

interface VisitorData {
  visitorCount: number;
}

interface GoalData {
  goalName: string;
  progress: number;
}

export function AnalyticsDashboard(): JSX.Element {
  const [visitorData, setVisitorData] = useState<VisitorData>({ visitorCount: 0 });
  const [goalData, setGoalData] = useState<GoalData[]>([]);

  useEffect(() => {
    const fetchVisitorData = async () => {
      const response = await fetch("/api/tracking-api/visitors");
      const data: VisitorData = await response.json();
      setVisitorData(data);
    };

    const fetchGoalData = async () => {
      const response = await fetch("/api/tracking-api/goals");
      const data: GoalData[] = await response.json();
      setGoalData(data);
    };

    fetchVisitorData();
    fetchGoalData();

    const intervalId = setInterval(() => {
      fetchVisitorData();
      fetchGoalData();
    }, 5000);

    return () => clearInterval(intervalId);
  }, []);

  return (
    <div>
      <h1>Analytics Dashboard</h1>
      <div>
        <h2>Visitors</h2>
        <p>Current Visitors: {visitorData.visitorCount}</p>
      </div>
      <div>
        <h2>Goals</h2>
        <ul>
          {goalData.map((goal) => (
            <li key={goal.goalName}>{goal.goalName}: {goal.progress}%</li>
          ))}
        </ul>
      </div>
    </div>
  );
}

