  const stmt = db.prepare('UPDATE posts SET title = ?, content = ?, status = ?, updatedAt = CURRENT_TIMESTAMP WHERE id = ?');
  stmt.run(title, content, status, id);
}

export function deletePost(id: number): void {
  const stmt = db.prepare('DELETE FROM posts WHERE id = ?');
  stmt.run(id);
}

