interface Service {
  id: number;
  name: string;
  status: "up" | "down";
}

export function StatusDashboard(): JSX.Element {
  const [services, setServices] = useState<Service[]>([]);

  useEffect(() => {
    const fetchServiceStatus = async () => {
      const response = await fetch("/api/monitor-checker");
      const data = await response.json();
      setServices(data);
    };

    fetchServiceStatus();
    const intervalId = setInterval(fetchServiceStatus, 5000);

    return () => clearInterval(intervalId);
  }, []);

  return (
    <div>
      <h1>Status Dashboard</h1>
      <ul>
        {services.map((service) => (
          <li key={service.id} style={{ color: service.status === "up" ? "green" : "red" }}>
            {service.name} - {service.status}
          </li>
        ))}
      </ul>
    </div>
  );
}

