}

export function insertAvailabilityRule(eventTypeId: number, startTime: string, endTime: string, daysOfWeek: number[]): void {
  db.prepare(`INSERT INTO availability_rules (event_type_id, start_time, end_time, days_of_week) VALUES (?, ?, ?, ?)`).run(eventTypeId, startTime, endTime, JSON.stringify(daysOfWeek));
}

export function getAvailabilityRules(eventTypeId: number): AvailabilityRule[] {
  return db.prepare(`SELECT *, json_extract(days_of_week, '$') AS days_of_week FROM availability_rules WHERE event_type_id = ?`).all(eventTypeId) as unknown as AvailabilityRule[];
}

export function insertBooking(eventTypeId: number, startTime: string, endTime: string, userId: number): void {
  db.prepare(`INSERT INTO bookings (event_type_id, start_time, end_time, user_id) VALUES (?, ?, ?, ?)`).run(eventTypeId, startTime, endTime, userId);
}

export function getBookings(eventTypeId: number): Booking[] {
  return db.prepare(`SELECT * FROM bookings WHERE event_type_id = ?`).all(eventTypeId) as unknown as Booking[];
}

