  description: string;
  price: number;
}

export interface Order {
  id: number;
  productId: number;
  quantity: number;
  orderDate: string;
}

export interface BusinessModelData {
  id: number;
  key: string;
  value: string;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    price REAL NOT NULL
  );

  CREATE TABLE IF NOT EXISTS orders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    productId INTEGER NOT NULL,
    quantity INTEGER NOT NULL,
    orderDate TEXT NOT NULL,
    FOREIGN KEY (productId) REFERENCES products(id)
  );

  CREATE TABLE IF NOT EXISTS business_model_data (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    key TEXT NOT NULL,
    value TEXT NOT NULL
  );
`);

export function insertProduct(name: string, description: string, price: number): void {
  db.prepare(`INSERT INTO products (name, description, price) VALUES (?, ?, ?)`).run(name, description, price);
}

export function getProductById(id: number): Product | undefined {
  return db.prepare(`SELECT * FROM products WHERE id = ?`).get(id) as unknown as Product;
}

export function getAllProducts(): Product[] {
  return db.prepare(`SELECT * FROM products`).all() as unknown as Product[];
}

export function insertOrder(productId: number, quantity: number, orderDate: string): void {
  db.prepare(`INSERT INTO orders (productId, quantity, orderDate) VALUES (?, ?, ?)`).run(productId, quantity, orderDate);
}

export function getOrderById(id: number): Order | undefined {
  return db.prepare(`SELECT * FROM orders WHERE id = ?`).get(id) as unknown as Order;
}

export function getAllOrders(): Order[] {
  return db.prepare(`SELECT * FROM orders`).all() as unknown as Order[];
}

export function insertBusinessModelData(key: string, value: string): void {
  db.prepare(`INSERT INTO business_model_data (key, value) VALUES (?, ?)`).run(key, value);
}

export function getBusinessModelDataByKey(key: string): BusinessModelData | undefined {
  return db.prepare(`SELECT * FROM business_model_data WHERE key = ?`).get(key) as unknown as BusinessModelData;
}

export function getAllBusinessModelData(): BusinessModelData[] {
  return db.prepare(`SELECT * FROM business_model_data`).all() as unknown as BusinessModelData[];
}

