export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process GET requests
  if (req.method !== "GET") {
    return next();
  }

  // Define a list of blocked domains for adult content
  const blockedDomains = [
    "example.com",
    "another-example.com"
    // Add more domains as needed
  ];

  // Check if the requested host is in the blocked list
  if (blockedDomains.includes(req.hostname)) {
    res.status(403).send("Access to this site is blocked due to parental controls.");
    return;
  }

  // Enforce safe search on supported search engines
  if (req.hostname === "www.google.com" && req.query.q) {
    const query = new URLSearchParams(req.query as Record<string, string>).toString();
    if (!query.includes("safe=active")) {
      res.redirect(`https://www.google.com/search?${query}&safe=active`);
      return;
    }
  }

  // If the request is not blocked or redirected, proceed to the next middleware
  next();
}

