import type { Request, Response, NextFunction } from "express";
import * as crypto from "crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST and PUT requests, as these are the ones likely to contain data to encrypt.
  if (req.method !== "POST" && req.method !== "PUT") {
    return next();
  }

  // For demonstration purposes, we'll assume the data to encrypt is in req.body.data.
  // In a real-world scenario, you would need to handle different data structures and possibly multiple fields.
  if (!req.body || typeof req.body.data !== "string") {
    return next();
  }

  const algorithm = "aes-256-cbc";
  const key = crypto.randomBytes(32); // 256-bit key
  const iv = crypto.randomBytes(16); // Initialization vector

  const cipher = crypto.createCipheriv(algorithm, Buffer.from(key), iv);
  let encrypted = cipher.update(req.body.data, "utf8", "hex");
  encrypted += cipher.final("hex");

  // Attach the IV and key to the encrypted data for decryption later.
  // In practice, you should securely store the key and IV, possibly using environment variables or a secure vault.
  req.body.data = {
    iv: iv.toString("hex"),
    encryptedData: encrypted,
    key: key.toString("hex") // This should not be included in production code; keys should be securely managed.
  };

  next();
}

