export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Define the protected methods and paths
  const protectedMethods = ["POST", "PUT", "DELETE"];
  const protectedPaths = ["/shorturls", "/shorturls/"];

  // Check if the request method and path are protected
  if (!protectedMethods.includes(req.method) || !protectedPaths.some(path => req.path.startsWith(path))) {
    return next();
  }

  // Get the API key from the request headers
  const apiKey = req.headers["x-api-key"] as string | undefined;

  // Validate the API key
  if (!apiKey || apiKey !== process.env.API_KEY) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // If the API key is valid, proceed to the next middleware or route handler
  next();
}

