import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Define the paths and methods that require role-based login validation
  const protectedPaths = [
    "/admin",
    "/client"
  ];

  // Check if the request path is one of the protected paths
  if (!protectedPaths.some(path => req.path.startsWith(path))) {
    return next();
  }

  // Extract the role from the request headers or session (example assumes headers)
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Validate the user role
  if (req.path.startsWith("/admin") && userRole !== "administrator") {
    res.status(403).send("Access denied: Administrator role required.");
    return;
  }

  if (req.path.startsWith("/client") && userRole !== "client") {
    res.status(403).send("Access denied: Client role required.");
    return;
  }

  // If the role is valid, proceed to the next middleware or route handler
  next();
}

