  if (!req.path.startsWith(apiPathPrefix)) {
    // If the request is not targeting the API, pass it through without validation.
    return next();
  }

  // Extract the access token from the request headers.
  const accessToken = req.headers["authorization"]?.split(" ")[1];

  // Check if the access token is present and valid.
  if (!accessToken || !isValidAccessToken(accessToken)) {
    // If the access token is missing or invalid, respond with a 401 Unauthorized status.
    res.status(401).json({ error: "Unauthorized: Missing or invalid access token." });
    return;
  }

  // If the access token is valid, proceed to the next middleware or route handler.
  next();
}

