interface Timer {
  id: number;
  projectId: number;
  startTime: Date;
  endTime?: Date;
  tags: string[];
}

export function TimerDashboard(): JSX.Element {
  const [timers, setTimers] = useState<Timer[]>([]);
  const [currentTimer, setCurrentTimer] = useState<Timer | null>(null);

  const startTimer = (projectId: number, tags: string[]): void => {
    const newTimer: Timer = {
      id: Date.now(),
      projectId,
      startTime: new Date(),
      tags,
    };
    setTimers([...timers, newTimer]);
    setCurrentTimer(newTimer);
  };

  const stopTimer = (): void => {
    if (currentTimer) {
      const stoppedTimer: Timer = {
        ...currentTimer,
        endTime: new Date(),
      };
      setTimers(timers.map(timer => (timer.id === stoppedTimer.id ? stoppedTimer : timer)));
      setCurrentTimer(null);
    }
  };

  return (
    <div>
      <h1>Timer Dashboard</h1>
      <button onClick={() => startTimer(1, ["development"])}>Start Timer</button>
      <button onClick={stopTimer} disabled={!currentTimer}>Stop Timer</button>
      <ul>
        {timers.map(timer => (
          <li key={timer.id}>
            Project {timer.projectId} - Started at {timer.startTime.toLocaleString()} - Tags: {timer.tags.join(", ")}
            {timer.endTime && <> - Ended at {timer.endTime.toLocaleString()}</>}
          </li>
        ))}
      </ul>
    </div>
  );
}

