import type { Request, Response, NextFunction } from "express";

interface AccessRule {
  domain: string;
  userGroup: string;
  uri: string;
  method: string;
  networkLocation: string;
}

const accessRules: AccessRule[] = [
  // Example rule: Allow GET requests to /api/data for users in 'admin' group from 'office' network
  { domain: "example.com", userGroup: "admin", uri: "/api/data", method: "GET", networkLocation: "office" },
  // Add more rules as needed
];

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const { host, path, method } = req;
  const networkLocation = req.headers["x-forwarded-for"] || req.socket.remoteAddress;

  // Check if the request matches any access rule
  const isAllowed = accessRules.some(rule => {
    return (
      rule.domain === host &&
      rule.uri === path &&
      rule.method === method &&
      rule.networkLocation === networkLocation
    );
  });

  if (isAllowed) {
    next();
  } else {
    res.status(403).send("Access Denied");
  }
}

