    // For demonstration purposes, let's assume these are the default credentials
    const defaultUsername = "admin";
    const defaultPassword = "password";

    // Check if the provided credentials are the default ones
    if (username === defaultUsername && password === defaultPassword) {
      // Password change is required on first login
      res.status(403).send("Password change required on first login.");
      return;
    }
  }

  // Call next for all other requests
  next();
}

