import type { Request, Response, NextFunction } from "express";

const API_KEY = process.env.API_KEY;
const PEPPER = process.env.PEPPER;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is intended to protect every request, so no early exit based on method or path.

  const providedApiKey = req.headers["x-api-key"] as string | undefined;

  if (!providedApiKey || providedApiKey !== `${API_KEY}${PEPPER}`) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}

import React, { FC, useState, useEffect } from "react";

interface Item {
  id: number;
  name: string;
  location: string;
  category: string;
  tags: string[];
}

export function InventoryBrowser(): JSX.Element {
  const [items, setItems] = useState<Item[]>([]);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [locationFilter, setLocationFilter] = useState<string>("");
  const [categoryFilter, setCategoryFilter] = useState<string>("");
  const [tagsFilter, setTagsFilter] = useState<string[]>([]);

  useEffect(() => {
    fetch("/api/inventory-api")
      .then(response => response.json())
      .then(data => setItems(data));
  }, []);

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    setSearchTerm(event.target.value);
  };

  const handleLocationChange = (event: React.ChangeEvent<HTMLSelectElement>): void => {
    setLocationFilter(event.target.value);
  };

  const handleCategoryChange = (event: React.ChangeEvent<HTMLSelectElement>): void => {
    setCategoryFilter(event.target.value);
  };

  const handleTagsChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    const tag = event.target.value;
    if (event.target.checked) {
      setTagsFilter([...tagsFilter, tag]);
    } else {
      setTagsFilter(tagsFilter.filter(t => t !== tag));
    }
  };

  const filteredItems = items.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesLocation = locationFilter ? item.location === locationFilter : true;
    const matchesCategory = categoryFilter ? item.category === categoryFilter : true;
    const matchesTags = tagsFilter.length > 0 ? tagsFilter.every(tag => item.tags.includes(tag)) : true;
    return matchesSearch && matchesLocation && matchesCategory && matchesTags;
  });

  return (
    <div>
      <input
        type="text"
        placeholder="Search..."
        value={searchTerm}
        onChange={handleSearchChange}
      />
      <select value={locationFilter} onChange={handleLocationChange}>
        <option value="">All Locations</option>
        <option value="Kitchen">Kitchen</option>
        <option value="Living Room">Living Room</option>
        <option value="Bedroom">Bedroom</option>
        {/* Add more locations as needed */}
      </select>
      <select value={categoryFilter} onChange={handleCategoryChange}>
        <option value="">All Categories</option>
        <option value="Furniture">Furniture</option>
        <option value="Appliances">Appliances</option>
        <option value="Decor">Decor</option>
        {/* Add more categories as needed */}
      </select>
      <div>
        <label>
          <input
            type="checkbox"
            value="wood"
            checked={tagsFilter.includes("wood")}
            onChange={handleTagsChange}
          />
          Wood
        </label>
        <label>
          <input
            type="checkbox"
            value="new"
            checked={tagsFilter.includes("new")}
            onChange={handleTagsChange}
          />
          New
        </label>
        <label>
          <input
            type="checkbox"
            value="used"
            checked={tagsFilter.includes("used")}
            onChange={handleTagsChange}
          />
          Used
        </label>
        {/* Add more tags as needed */}
      </div>
      <ul>
        {filteredItems.map(item => (
          <li key={item.id}>{item.name} - {item.location} - {item.category} - {item.tags.join(", ")}</li>
        ))}
      </ul>
    </div>
  );
}

