  date: string;
}

interface MonthlyTotal {
  month: string;
  totalsByCategory: Record<string, number>;
}

export function MonthlyTotalsView(): JSX.Element {
  const [monthlyTotals, setMonthlyTotals] = useState<MonthlyTotal[]>([]);

  useEffect(() => {
    fetch("/api/expenses-api")
      .then(response => response.json())
      .then((expenses: Expense[]) => {
        const totalsByMonth: Record<string, Record<string, number>> = {};

        expenses.forEach(expense => {
          const month = new Date(expense.date).toLocaleString("default", { year: "numeric", month: "long" });
          if (!totalsByMonth[month]) {
            totalsByMonth[month] = {};
          }
          if (!totalsByMonth[month][expense.category]) {
            totalsByMonth[month][expense.category] = 0;
          }
          totalsByMonth[month][expense.category] += expense.amount;
        });

        const formattedTotals: MonthlyTotal[] = Object.keys(totalsByMonth).map(month => ({
          month,
          totalsByCategory: totalsByMonth[month],
        }));

        setMonthlyTotals(formattedTotals);
      });
  }, []);

  return (
    <div>
      <h1>Monthly Totals</h1>
      {monthlyTotals.map(total => (
        <div key={total.month}>
          <h2>{total.month}</h2>
          <ul>
            {Object.entries(total.totalsByCategory).map(([category, amount]) => (
              <li key={category}>{category}: ${amount.toFixed(2)}</li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
}

