import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this middleware to DELETE requests to the /channels/:channelId/messages/:messageId path
  if (req.method !== "DELETE" || !req.path.startsWith("/channels/")) {
    return next();
  }

  // Assuming user information is attached to the request by a previous middleware
  const user = req.user as { isAdmin: boolean; channelId: number } | undefined;

  if (!user || !user.isAdmin) {
    return res.status(403).send("Forbidden: Only admins can delete messages.");
  }

  // Check if the user is in the same channel as the message
  const channelIdFromPath = Number(req.params.channelId);
  if (user.channelId !== channelIdFromPath) {
