import React, { FC, useState, useEffect } from "react";

interface Message {
  id: number;
  user: string;
  content: string;
  timestamp: string;
}

interface Channel {
  id: number;
  name: string;
}

export function ChatInterface(): JSX.Element {
  const [messages, setMessages] = useState<Message[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<number | null>(null);
  const [newMessage, setNewMessage] = useState<string>("");

  useEffect(() => {
    fetch("/api/channels-api")
      .then(response => response.json())
      .then(data => setChannels(data));
  }, []);

  useEffect(() => {
    if (currentChannel !== null) {
      fetch(`/api/channels-api/${currentChannel}/messages`)
        .then(response => response.json())
        .then(data => setMessages(data));
    }
  }, [currentChannel]);

  const handleSendMessage = async () => {
    if (currentChannel !== null && newMessage.trim() !== "") {
      const response = await fetch(`/api/channels-api/${currentChannel}/messages`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ content: newMessage }),
      });

      if (response.ok) {
        setNewMessage("");
        // Refresh messages
        fetch(`/api/channels-api/${currentChannel}/messages`)
          .then(response => response.json())
          .then(data => setMessages(data));
      }
    }
  };

  return (
    <div>
      <h1>Chat Interface</h1>
      <select onChange={(e) => setCurrentChannel(Number(e.target.value))} value={currentChannel ?? ""}>
        <option value="">Select a channel</option>
        {channels.map(channel => (
          <option key={channel.id} value={channel.id}>{channel.name}</option>
        ))}
      </select>
      <div>
        {messages.map(message => (
          <div key={message.id}>
            <strong>{message.user}</strong>: {message.content} <span>({message.timestamp})</span>
          </div>
        ))}
      </div>
      <input
        type="text"
        value={newMessage}
        onChange={(e) => setNewMessage(e.target.value)}
        placeholder="Type a message..."
      />
      <button onClick={handleSendMessage}>Send</button>
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this middleware to DELETE requests to the /channels/:channelId/messages/:messageId path
  if (req.method !== "DELETE" || !req.path.startsWith("/channels/")) {
    return next();
  }

  // Assuming user information is attached to the request by a previous middleware
  const user = req.user as { isAdmin: boolean; channelId: number } | undefined;

  if (!user || !user.isAdmin) {
    return res.status(403).send("Forbidden: Only admins can delete messages.");
  }

  // Check if the user is in the same channel as the message
  const channelIdFromPath = Number(req.params.channelId);
  if (user.channelId !== channelIdFromPath) {
    return res.status(403).send("Forbidden: You can only delete messages in channels you belong to.");
  }

  next();
}

