import { DatabaseSync } from "node:sqlite";

export interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
  copyCount: number;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    author TEXT NOT NULL,
    isbn TEXT NOT NULL UNIQUE,
    copyCount INTEGER NOT NULL
  );
`);

export function insertBook(title: string, author: string, isbn: string, copyCount: number): void {
  const stmt = db.prepare(`INSERT INTO books (title, author, isbn, copyCount) VALUES (?, ?, ?, ?)`);
  stmt.run(title, author, isbn, copyCount);
}

export function getBooks(): Book[] {
  const stmt = db.prepare(`SELECT * FROM books`);
  return stmt.all() as unknown as Book[];
}

export function getBookById(id: number): Book | undefined {
  const stmt = db.prepare(`SELECT * FROM books WHERE id = ?`);
  return stmt.get(id) as unknown as Book | undefined;
}

export function updateBook(id: number, title: string, author: string, isbn: string, copyCount: number): void {
  const stmt = db.prepare(`UPDATE books SET title = ?, author = ?, isbn = ?, copyCount = ? WHERE id = ?`);
  stmt.run(title, author, isbn, copyCount, id);
}

export function deleteBook(id: number): void {
  const stmt = db.prepare(`DELETE FROM books WHERE id = ?`);
  stmt.run(id);
}

