db.exec(`
  CREATE TABLE rooms (
    roomCode TEXT PRIMARY KEY,
    playerCount INTEGER NOT NULL
  );
`);

export function createRoom(roomCode: string, playerCount: number): void {
  db.prepare(`INSERT INTO rooms (roomCode, playerCount) VALUES (?, ?)`).run(roomCode, playerCount);
}

export function getRoom(roomCode: string): Room | undefined {
  const stmt = db.prepare(`SELECT * FROM rooms WHERE roomCode = ?`).get(roomCode);
  return stmt as unknown as Room;
}

