  db.prepare(`UPDATE rooms SET playerCount = ? WHERE roomCode = ?`).run(playerCount, roomCode);
}

export function deleteRoom(roomCode: string): void {
  db.prepare(`DELETE FROM rooms WHERE roomCode = ?`).run(roomCode);
}

