    stallNumber INTEGER NOT NULL,
    weekendDate TEXT NOT NULL,
    PRIMARY KEY (vendorId, weekendDate)
  );
`);

export function insertReservation(vendorId: number, stallNumber: number, weekendDate: string): void {
  db.prepare(`INSERT INTO reservations (vendorId, stallNumber, weekendDate) VALUES (?, ?, ?)`).run(vendorId, stallNumber, weekendDate);
