}

import { Router, type Request, type Response } from "express";
import { Reservation, insertReservation, getReservationsByWeekendDate, deleteReservation } from "../db/reservations-table";

export const router = Router();

router.post("/create", (req: Request, res: Response) => {
  const { vendorId, stallNumber, weekendDate }: { vendorId: number, stallNumber: number, weekendDate: string } = req.body;

  const existingReservations = getReservationsByWeekendDate(weekendDate);
  const isStallAlreadyReserved = existingReservations.some(reservation => reservation.stallNumber === stallNumber);

  if (isStallAlreadyReserved) {
    res.status(409).send("Stall is already reserved for this date.");
    return;
  }

  insertReservation(vendorId, stallNumber, weekendDate);
  res.status(201).send("Reservation created successfully.");
});

router.delete("/cancel", (req: Request, res: Response) => {
  const { vendorId, weekendDate }: { vendorId: number, weekendDate: string } = req.body;

  // Assuming only managers can cancel reservations, this should be checked elsewhere in the application
  // For this example, we'll proceed with cancellation

  deleteReservation(vendorId, weekendDate);
  res.status(200).send("Reservation cancelled successfully.");
});

