export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this guard to DELETE requests to reservation routes
  if (req.method === "DELETE" && req.path.startsWith(reservationsRouter.path)) {
    // Check if the user is authenticated and has manager privileges
    if (!req.user || !req.user.isManager) {
