export function MarketManagerDashboard(): JSX.Element {
  const [reservations, setReservations] = useState<Reservation[]>([]);

  useEffect(() => {
    fetch("/api/reservations-api")
      .then(response => response.json())
      .then(data => setReservations(data));
  }, []);

  const handleCancelReservation = (id: number) => {
    fetch(`/api/reservations-api/${id}`, { method: "DELETE" })
      .then(() => setReservations(reservations.filter(reservation => reservation.id !== id)));
  };

  return (
    <div>
      <h1>Market Manager Dashboard</h1>
      <ul>
        {reservations.map(reservation => (
          <li key={reservation.id}>
            Stall {reservation.stallNumber} reserved by {reservation.customerName} on {reservation.reservationDate}
            <button onClick={() => handleCancelReservation(reservation.id)}>Cancel</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

