import { Router, type Request, type Response } from "express";
import { getRoomById } from "../db/rooms-table";
import { getReassignmentsByRoomId } from "../db/reassignments-table";

export const router = Router();

router.post("/reassign", async (req: Request, res: Response) => {
  const { targetHousekeeperId, roomId } = req.body;

  if (typeof targetHousekeeperId !== "number" || typeof roomId !== "number") {
    res.status(400).send("Invalid input");
    return;
  }

  const room = getRoomById(roomId);

  if (!room) {
    res.status(404).send("Room not found");
    return;
  }

  if (room.housekeeperId === targetHousekeeperId) {
    res.status(409).send("Target housekeeper already assigned to this room");
    return;
  }

  const reassignments = getReassignmentsByRoomId(roomId);

  if (reassignments.some(reassignment => reassignment.targetHousekeeperId === targetHousekeeperId)) {
    res.status(409).send("Target housekeeper already has a pending reassignment for this room");
    return;
  }

  res.status(200).send("Reassignment allowed");
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this guard to POST requests to the reassignment endpoint
  if (req.method !== "POST" || !req.path.startsWith("/api/housekeeping/reassign")) {
    return next();
  }

  // Check if the user is a supervisor
  const userRole = req.headers["user-role"] as string | undefined;
  if (userRole !== "supervisor") {
    res.status(403).send("Forbidden: Only supervisors can reassign tasks.");
    return;
  }

  // If the user is a supervisor, proceed to the next middleware or route handler
  next();
}

