  const studentId = Number(req.params.studentId);
  const bookIsbn = req.params.bookIsbn;

  const checkout = getCheckout(studentId, bookIsbn);
  if (!checkout) {
    res.status(404).send("Checkout not found");
    return;
  }

  const existingWaiver = getWaiver(studentId, bookIsbn);
  if (existingWaiver && existingWaiver.waived) {
    res.status(200).send("Fee already waived");
    return;
  }

  insertWaiver(studentId, bookIsbn, true);
