import { Router, type Request, type Response } from "express";
import { getTimesheets } from "../db/timesheets-table";
import { getApproval } from "../db/approvals-table";

export const router = Router();

router.post("/approve", (req: Request, res: Response) => {
  const { timesheetId, partnerId } = req.body;

  if (typeof timesheetId !== "number" || typeof partnerId !== "number") {
    res.status(400).send("Invalid input");
    return;
  }

  const timesheet = getTimesheets().find(ts => ts.associateId === timesheetId);

  if (!timesheet) {
    res.status(404).send("Timesheet not found");
    return;
  }

  const approval = getApproval(partnerId, timesheetId);

  if (!approval || approval.approvalStatus !== "approved") {
    res.status(403).send("Timesheet not approved");
    return;
  }

  res.status(200).send("Timesheet approved");
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply the guard to POST requests to the /timesheets endpoint
  if (req.method !== "POST" || req.path !== "/timesheets") {
    return next();
  }

  // Check if the timesheet entry has been approved by a partner
  const { approvedByPartner } = req.body;

  if (!approvedByPartner) {
    res.status(403).send("Timesheet entry must be approved by a partner first.");
    return;
  }

  next();
}

