interface Show {
  id: number;
  title: string;
}

interface Slot {
  id: number;
  time: string;
}

export function AuditionSignupForm(): JSX.Element {
  const [shows, setShows] = useState<Show[]>([]);
  const [slots, setSlots] = useState<Slot[]>([]);
  const [selectedShowId, setSelectedShowId] = useState<number | null>(null);
  const [selectedSlotId, setSelectedSlotId] = useState<number | null>(null);
  const [actorName, setActorName] = useState<string>("");

  const fetchShows = async (): Promise<void> => {
    const response = await fetch("/api/auditions-api/shows");
    const data = await response.json();
    setShows(data);
  };

  const fetchSlots = async (showId: number): Promise<void> => {
    const response = await fetch(`/api/auditions-api/slots?showId=${showId}`);
    const data = await response.json();
    setSlots(data);
  };

  const handleShowChange = (event: React.ChangeEvent<HTMLSelectElement>): void => {
    const showId = Number(event.target.value);
    setSelectedShowId(showId);
    fetchSlots(showId);
  };

  const handleSlotChange = (event: React.ChangeEvent<HTMLSelectElement>): void => {
    setSelectedSlotId(Number(event.target.value));
  };

  const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    setActorName(event.target.value);
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
    event.preventDefault();
    if (selectedShowId !== null && selectedSlotId !== null) {
      const response = await fetch("/api/auditions-api/signup", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          showId: selectedShowId,
          slotId: selectedSlotId,
          actorName: actorName,
        }),
      });
      if (response.ok) {
        alert("Signup successful!");
      }
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="show">Choose a show:</label>
        <select id="show" value={selectedShowId === null ? "" : selectedShowId.toString()} onChange={handleShowChange} required>
          <option value="">--Please choose a show--</option>
          {shows.map((show) => (
            <option key={show.id} value={show.id}>{show.title}</option>
          ))}
        </select>
      </div>
      <div>
        <label htmlFor="slot">Choose a slot:</label>
        <select id="slot" value={selectedSlotId === null ? "" : selectedSlotId.toString()} onChange={handleSlotChange} required>
          <option value="">--Please choose a slot--</option>
          {slots.map((slot) => (
            <option key={slot.id} value={slot.id}>{slot.time}</option>
          ))}
        </select>
      </div>
      <div>
        <label htmlFor="name">Your name:</label>
        <input type="text" id="name" value={actorName} onChange={handleNameChange} required />
      </div>
      <button type="submit">Sign Up</button>
    </form>
  );
}

