import { Musician, getMusicianById } from "../db/musicians-table";

export const router = Router();

router.get("/rehearsals", (req: Request, res: Response): void => {
  const rehearsals: Rehearsal[] = getAllRehearsals();
  res.json(rehearsals);
});

router.get("/rehearsals/:id", (req: Request, res: Response): void => {
  const rehearsalId: number = Number(req.params.id);
  const rehearsal: Rehearsal | undefined = getRehearsalById(rehearsalId);
  if (rehearsal) {
    res.json(rehearsal);
  } else {
    res.status(404).send("Rehearsal not found");
  }
});

router.post("/rehearsals", (req: Request, res: Response): void => {
  const { date, time, confirmedMusicianCount }: { date: string, time: string, confirmedMusicianCount: number } = req.body;
  insertRehearsal(date, time, confirmedMusicianCount);
  res.status(201).send("Rehearsal created");
});

router.post("/rehearsals/:id/attendance", (req: Request, res: Response): void => {
  const rehearsalId: number = Number(req.params.id);
  const { musicianId }: { musicianId: number } = req.body;
  const rehearsal: Rehearsal | undefined = getRehearsalById(rehearsalId);
  const musician: Musician | undefined = getMusicianById(musicianId);

  if (!rehearsal || !musician) {
    res.status(404).send("Rehearsal or musician not found");
    return;
  }

  // Assuming attendance is recorded by incrementing confirmedMusicianCount
  // This is a placeholder for actual attendance recording logic
  // For now, we just increment the count
  rehearsal.confirmedMusicianCount += 1;
  res.send("Attendance recorded");
});

router.delete("/rehearsals/:id/cancel", (req: Request, res: Response): void => {
  // Placeholder for cancellation logic
  // For now, we just send a response indicating cancellation
  res.send("Rehearsal cancelled");
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this guard to POST requests to the cancellation endpoint
  if (req.method !== "POST" || req.path !== "/cancel-rehearsal") {
    return next();
  }

  // Assume the conductor's ID is stored in req.body.conductorId and the user's ID in req.body.userId
  const conductorId = req.body.conductorId;
  const userId = req.body.userId;

  if (conductorId !== userId) {
    res.status(403).send("Cancellation is only allowed by the conductor.");
  } else {
    next();
  }
}

