import { Router, type Request, type Response } from "express";
import { getMemberById } from "../db/members-table";
import { insertCheckin, getCheckinsByMember } from "../db/checkins-table";

export const router = Router();

router.get("/status/:id", (req: Request, res: Response) => {
  const memberId = Number(req.params.id);
  const member = getMemberById(memberId);

  if (!member) {
    res.status(404).json({ message: "Member not found" });
    return;
  }

  res.json({ id: member.id, name: member.name, membershipStatus: member.membershipStatus });
});

router.post("/checkin", (req: Request, res: Response) => {
  const { dogId, memberId } = req.body;
  const timestamp = Date.now();

  if (typeof dogId !== "number" || typeof memberId !== "number") {
    res.status(400).json({ message: "Invalid input" });
    return;
  }

  const member = getMemberById(memberId);

  if (!member || member.membershipStatus !== "active") {
    res.status(403).json({ message: "Membership inactive or invalid" });
    return;
  }

  insertCheckin(dogId, memberId, timestamp);
  res.status(201).json({ message: "Checkin successful" });
});

router.delete("/revoke/:id", (req: Request, res: Response) => {
  const memberId = Number(req.params.id);
  const member = getMemberById(memberId);

  if (!member) {
    res.status(404).json({ message: "Member not found" });
    return;
  }

  // Assuming revoking membership means setting status to 'inactive'
  // This would typically involve an update operation, but the provided API does not support it.
  // For demonstration, we'll just respond with a success message.
  res.json({ message: "Membership revoked" });
});

