import { Router, type Request, type Response } from "express";
import { Keg, getKegById, getAllKegs, updateKegStockQuantity, deleteKegById } from "../db/kegs-table";
import { Brewer, getBrewerById } from "../db/brewers-table";
import { markBatchAsSpoiled, getSpoiledBatches } from "../db/batch-spoils-table";

export const router = Router();

router.get("/kegs", (req: Request, res: Response) => {
  const kegs = getAllKegs();
  res.json(kegs);
});

router.get("/kegs/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const keg = getKegById(id);
  if (keg) {
    res.json(keg);
  } else {
    res.status(404).send(`Keg with id ${id} not found`);
  }
});

router.put("/kegs/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { stockQuantity } = req.body;
  const keg = getKegById(id);
  if (keg) {
    updateKegStockQuantity(id, stockQuantity);
    res.status(200).send(`Updated keg with id ${id}`);
  } else {
    res.status(404).send(`Keg with id ${id} not found`);
  }
});

router.delete("/kegs/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const keg = getKegById(id);
  if (keg) {
    deleteKegById(id);
    res.status(200).send(`Deleted keg with id ${id}`);
  } else {
    res.status(404).send(`Keg with id ${id} not found`);
  }
});

router.post("/batches/:batchId/spoil", (req: Request, res: Response) => {
  const batchId = Number(req.params.batchId);
  const brewerId = Number(req.body.brewerId);
  const brewer = getBrewerById(brewerId);
  if (brewer && brewer.role === "head brewer") {
    markBatchAsSpoiled(batchId, brewerId);
    res.status(200).send(`Marked batch with id ${batchId} as spoiled`);
  } else {
    res.status(403).send(`Brewer with id ${brewerId} is not authorized to spoil batches`);
  }
});

router.get("/batches/spoiled", (req: Request, res: Response) => {
  const spoiledBatches = getSpoiledBatches();
  res.json(spoiledBatches);
});

import type { Request, Response, NextFunction } from "express";
import { router } from "../routes/inventory-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this middleware to POST requests to the specific route
  if (req.method !== "POST" || req.path !== "/inventory/mark-spoiled") {
    return next();
  }

  // Check if the user has the head brewer role
  const userRole = req.headers["user-role"] as string | undefined;
  if (userRole !== "head-brewer") {
    res.status(403).send("Forbidden: Only the head brewer can mark a batch spoiled.");
    return;
  }

  // If the user is the head brewer, proceed to the next middleware or route handler
  next();
}

