import { Router, type Request, type Response } from "express";
import { Session, getAllSessions, getSessionByIds, insertSession, updateCompletionTimestamp } from "../db/sessions-table";
import { BillingRate, getBillingRates, getBillingRateById, updateBillingRate } from "../db/billing-rates-table";

export const router = Router();

router.post("/sessions", (req: Request, res: Response) => {
  const { tutorId, studentId, topic } = req.body;
  if (typeof tutorId !== "number" || typeof studentId !== "number" || typeof topic !== "string") {
    res.status(400).send("Invalid input");
    return;
  }
  insertSession(tutorId, studentId, topic);
  res.status(201).send("Session created");
});

router.put("/sessions/:tutorId/:studentId", (req: Request, res: Response) => {
  const tutorId = Number(req.params.tutorId);
  const studentId = Number(req.params.studentId);
  const { completionTimestamp } = req.body;
  if (isNaN(tutorId) || isNaN(studentId) || typeof completionTimestamp !== "number") {
    res.status(400).send("Invalid input");
    return;
  }
  const session = getSessionByIds(tutorId, studentId);
  if (!session) {
    res.status(404).send("Session not found");
    return;
  }
  updateCompletionTimestamp(tutorId, studentId, completionTimestamp);
  res.status(200).send("Session updated");
});

router.put("/billing-rates/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { subjectArea, hourlyRate } = req.body;
  if (isNaN(id) || typeof subjectArea !== "string" || typeof hourlyRate !== "number") {
    res.status(400).send("Invalid input");
    return;
  }
  const billingRate = getBillingRateById(id);
  if (!billingRate) {
    res.status(404).send("Billing rate not found");
    return;
  }
  // Validate director role here (not implemented as per requirement)
  updateBillingRate(id, subjectArea, hourlyRate);
  res.status(200).send("Billing rate updated");
});

