import React, { FC, useState } from "react";

export function HarvestEntryForm(): JSX.Element {
  const [grapeVariety, setGrapeVariety] = useState<string>("");
  const [weight, setWeight] = useState<number>(0);
  const [plotId, setPlotId] = useState<number>(0);

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
    event.preventDefault();
    const response = await fetch("/api/harvest-records-api", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ grapeVariety, weight, plotId }),
    });
    if (!response.ok) {
      console.error("Failed to submit harvest entry");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="grapeVariety">Grape Variety:</label>
        <input
          type="text"
          id="grapeVariety"
          value={grapeVariety}
          onChange={(e) => setGrapeVariety(e.target.value)}
          required
        />
      </div>
      <div>
        <label htmlFor="weight">Weight (kg):</label>
        <input
          type="number"
          id="weight"
          value={weight}
          onChange={(e) => setWeight(Number(e.target.value))}
          required
        />
      </div>
      <div>
        <label htmlFor="plotId">Plot ID:</label>
        <input
          type="number"
          id="plotId"
          value={plotId}
          onChange={(e) => setPlotId(Number(e.target.value))}
          required
        />
      </div>
      <button type="submit">Submit</button>
    </form>
  );
}

