export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply the guard to routes that require role-based access control
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE") {
    return next();
  }

  // Assuming the user role is attached to the request by an earlier middleware
  const userRole = (req as any).user?.role;

  if (userRole === "editor" || userRole === "admin") {
    next();
  } else {
    res.status(403).send("Access denied: insufficient permissions");
  }
}

