import { DatabaseSync } from "node:sqlite";

export interface AttendanceRow {
  singerId: number;
  date: string;
  status: 'present' | 'absent';
}

export const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE IF NOT EXISTS attendance (
    singerId INTEGER,
    date TEXT,
    status TEXT CHECK(status IN ('present', 'absent')),
    PRIMARY KEY (singerId, date)
  );
`);

export function recordAttendance(singerId: number, date: string, status: 'present' | 'absent'): void {
  db.prepare('INSERT OR REPLACE INTO attendance (singerId, date, status) VALUES (?, ?, ?)').run(singerId, date, status);
}

export function getAttendanceByDate(date: string): AttendanceRow[] {
  return db.prepare('SELECT * FROM attendance WHERE date = ?').all() as unknown as AttendanceRow[];
}

export function getAttendanceBySinger(singerId: number): AttendanceRow[] {
  return db.prepare('SELECT * FROM attendance WHERE singerId = ?').all() as unknown as AttendanceRow[];
}

import { Router, type Request, type Response } from "express";
import { recordAttendance, getAttendanceByDate, getAttendanceBySinger } from "../db/attendance-table";

export const router = Router();

router.post('/record', (req: Request, res: Response) => {
  const { singerId, date, status } = req.body;
  if (typeof singerId !== 'number' || typeof date !== 'string' || !['present', 'absent'].includes(status)) {
    res.status(400).send('Invalid input');
    return;
  }
  recordAttendance(singerId, date, status);
  res.status(201).send('Attendance recorded');
});

router.get('/by-date', (req: Request, res: Response) => {
  const { date } = req.query;
  if (typeof date !== 'string') {
    res.status(400).send('Invalid date');
    return;
  }
  const attendance = getAttendanceByDate(date);
  res.json(attendance);
});

router.get('/by-singer', (req: Request, res: Response) => {
  const { singerId } = req.query;
  if (typeof singerId !== 'string' || isNaN(Number(singerId))) {
    res.status(400).send('Invalid singerId');
    return;
  }
  const attendance = getAttendanceBySinger(Number(singerId));
  res.json(attendance);
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this guard to POST requests to the /excuses endpoint
  if (req.method !== "POST" || req.path !== "/excuses") {
    return next();
  }

  // Check if the authenticated user is the choir director
  const isAuthenticatedUserDirector = req.user && req.user.role === "director";

  if (!isAuthenticatedUserDirector) {
    res.status(403).send("Forbidden: Only the choir director can create excuses.");
  } else {
    next();
  }
}

import React, { FC, useState } from "react";

export function AttendanceMarkingPanel(): JSX.Element {
  const [status, setStatus] = useState<string>("unknown");

  const markPresence = async (): Promise<void> => {
    await fetch("/api/attendance-api", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ status: "present" }),
    });
    setStatus("present");
  };

  const markAbsence = async (): Promise<void> => {
    await fetch("/api/attendance-api", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ status: "absent" }),
    });
    setStatus("absent");
  };

  return (
    <div>
      <h1>Mark Your Attendance</h1>
      <button onClick={markPresence} disabled={status === "present"}>Mark Present</button>
      <button onClick={markAbsence} disabled={status === "absent"}>Mark Absent</button>
      <p>Your current status: {status}</p>
    </div>
  );
}

